class Gradebook:
    def __init__(self) -> None:
        self._assignments = {}
        self._grades = {}

    def add_assignment(self, name: str, weight: float, kind: str = "homework") -> None:
        self._assignments[name] = (weight, kind)

    def record(self, student: str, assignment: str, grade: float) -> None:
        if not (2.0 <= grade <= 5.0):
            raise ValueError("Grade must be between 2.0 and 5.0")
        if assignment not in self._assignments:
            raise KeyError(f"Unknown assignment: {assignment}")
        self._grades.setdefault(student, {})[assignment] = grade

    def average(self, student: str) -> float:
        grades = self._grades.get(student, {})
        if not grades:
            return 0.0

        # Identify quizzes and find the lowest quiz grade
        quizzes = [
            (name, grade) for name, grade in grades.items()
            if self._assignments[name][1] == "quiz"
        ]
        dropped_quiz = None
        if len(quizzes) > 1:
            dropped_quiz = min(quizzes, key=lambda x: x[1])[0]

        total_weight = 0.0
        weighted_sum = 0.0
        for name, grade in grades.items():
            if name == dropped_quiz:
                continue
            weight = self._assignments[name][0]
            weighted_sum += grade * weight
            total_weight += weight

        if total_weight == 0.0:
            return 0.0

        return round(weighted_sum / total_weight, 2)
